"use client";

import { useAppStore } from "@/store/app-store";
import { AuthLayout } from "./auth-layout";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { ArrowLeft, CircleHelp } from "lucide-react";

export function ForgotPasswordPage() {
  const { navigatePublic } = useAppStore();

  return (
    <AuthLayout title="Khôi phục mật khẩu">
      <div className="space-y-5">
        <Alert>
          <CircleHelp className="h-4 w-4" />
          <AlertTitle>Chức năng chưa được hỗ trợ</AlertTitle>
          <AlertDescription>
            Backend Spring Boot hiện chưa cung cấp API khôi phục mật khẩu hoặc gửi mã qua email. Chưa có email hay mã xác nhận nào được gửi.
          </AlertDescription>
        </Alert>
        <Button onClick={() => navigatePublic("login")} className="w-full gap-2">
          <ArrowLeft className="h-4 w-4" /> Quay lại đăng nhập
        </Button>
      </div>
    </AuthLayout>
  );
}
